import{_ as i,o as a,c as e,f as r}from"./chunks/framework.kvohTzd7.js";const b=JSON.parse('{"title":"非公式Pixivクライアントの保存・検索・ブックマーク機能を整えた話","description":"PalleriaをPixivクライアントとして整える中で、保存フロー、検索、ブックマーク、ミュート、アカウント管理をどう組み立てたかをまとめます。Pixivアプリ開発の実装メモとしても読める内容です。","frontmatter":{"title":"非公式Pixivクライアントの保存・検索・ブックマーク機能を整えた話","date":"2026-06-30","description":"PalleriaをPixivクライアントとして整える中で、保存フロー、検索、ブックマーク、ミュート、アカウント管理をどう組み立てたかをまとめます。Pixivアプリ開発の実装メモとしても読める内容です。","outline":2,"tags":["Pixiv","Android"]},"headers":[],"relativePath":"posts/palleria-development-blog/index.md","filePath":"posts/2026/palleria-development-blog.md","lastUpdated":1794490599000}'),t={name:"posts/palleria-development-blog/index.md"};function o(p,l,n,h,d,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<p>Pixiv の作品を「読む」「探す」「保存する」までひとつの流れで扱えるようにするために、画面構成、保存処理、設定、セッション管理をまとめて整えました。</p><p>今回の更新では、見た目の調整だけでなく、日常利用で効く部分を中心に詰めています。</p><h2 id="何を作っているか" tabindex="-1">何を作っているか <a class="header-anchor" href="#何を作っているか" aria-label="Permalink to &quot;何を作っているか&quot;">​</a></h2><p>Palleria は、Pixiv 向けのイラストビューアーです。<br> ホーム、ランキング、検索、ブックマーク、小説、もっと見るを軸にしながら、作品を見つけた後の操作まで含めて完結させることを狙っています。</p><p>特に重視しているのは次の3点です。</p><ul><li>作品を見つけた直後に、保存やブックマークへ自然につなげること</li><li>閲覧履歴や検索履歴を後から整理しやすくすること</li><li>端末内の保存状態やダウンロード進捗を把握しやすくすること</li></ul><p>単に作品一覧を表示するだけではなく、使い続けるほど便利になる導線を作るのが Palleria の方針です。</p><h2 id="今回の主な更新" tabindex="-1">今回の主な更新 <a class="header-anchor" href="#今回の主な更新" aria-label="Permalink to &quot;今回の主な更新&quot;">​</a></h2><h3 id="保存フローの整理" tabindex="-1">保存フローの整理 <a class="header-anchor" href="#保存フローの整理" aria-label="Permalink to &quot;保存フローの整理&quot;">​</a></h3><p>保存まわりは、Palleria の中でも特に力を入れている領域です。</p><ul><li>作者別フォルダ分け</li><li>作品別フォルダ分け</li><li>既定の保存場所の設定</li><li>オフライン保存</li><li>保存済み作品の一覧化</li><li>ダウンロード一覧の追加</li></ul><p>保存したファイルが端末のどこに入るか、今どの処理が進行中かを追えるようにしています。<br> ダウンロード一覧では、待機中・ダウンロード中・完了・失敗を状態別に分け、バックグラウンド処理をそのまま見える形にしました。</p><h3 id="作品詳細の操作性改善" tabindex="-1">作品詳細の操作性改善 <a class="header-anchor" href="#作品詳細の操作性改善" aria-label="Permalink to &quot;作品詳細の操作性改善&quot;">​</a></h3><p>作品詳細では、保存、共有、URLコピー、ブラウザで開く、ミュートなどの操作をまとめています。<br> さらに、保存時の確認ダイアログや長押し時の確認制御など、操作の粒度も調整できるようにしました。</p><p>加えて、ブックマーク時の連動動作も整理しています。</p><ul><li>作者を自動フォロー</li><li>タグを Watchlist 候補へ追加</li><li>保存と同時にブックマーク</li><li>ブックマーク時の公開範囲を調整</li></ul><p>作品を「見る」だけで終わらせず、あとで追い直せる状態へ自然に接続するための実装です。</p><h3 id="検索と再訪の強化" tabindex="-1">検索と再訪の強化 <a class="header-anchor" href="#検索と再訪の強化" aria-label="Permalink to &quot;検索と再訪の強化&quot;">​</a></h3><p>検索は、イラストとユーザーを分けて扱っています。<br> 検索対象、期間、並び順、ブックマーク数などを切り替えられるようにし、用途ごとに結果を絞り込める構成にしています。</p><p>あわせて、検索履歴、最近見た作品、おすすめタグも用意しています。<br> 毎回ゼロから探し直すのではなく、再訪しやすい入口を増やすことを意識しています。</p><h3 id="履歴・ミュート・データ管理" tabindex="-1">履歴・ミュート・データ管理 <a class="header-anchor" href="#履歴・ミュート・データ管理" aria-label="Permalink to &quot;履歴・ミュート・データ管理&quot;">​</a></h3><p>Palleria では、作品を見続けるほど効いてくる周辺機能もまとめて扱います。</p><ul><li>閲覧履歴の保存</li><li>検索履歴の保存</li><li>ユーザー・作品・タグのミュート</li><li>Watchlist タグ</li><li>お気に入りタグ</li><li>データのエクスポート / インポート</li></ul><p>履歴とミュートは、設定として単独で持つより、あとから整理できることのほうが重要です。<br> そのため、データ管理画面でまとめて見直せるようにしています。</p><h3 id="アカウントと復帰導線" tabindex="-1">アカウントと復帰導線 <a class="header-anchor" href="#アカウントと復帰導線" aria-label="Permalink to &quot;アカウントと復帰導線&quot;">​</a></h3><p>Pixiv 連携は、Web ログインと Refresh Token ログインの両方に対応しています。<br> アカウントの追加方法を分けることで、導入時の選択肢を確保しました。</p><ul><li>Web ログイン</li><li>Refresh Token ログイン</li><li>アカウント切り替え</li><li>ログアウト</li><li>認証切れ時の再ログイン案内</li></ul><p>認証が切れたときは、単にエラーで止めるのではなく、再ログインへ戻れる流れを用意しています。<br> セッションの寿命を前提にした復帰設計も、クライアントアプリでは重要だと考えています。</p><h2 id="設定まわり" tabindex="-1">設定まわり <a class="header-anchor" href="#設定まわり" aria-label="Permalink to &quot;設定まわり&quot;">​</a></h2><p>設定画面は、機能の一覧ではなく、使い方を調整するための入口としてまとめています。</p><ul><li>一般設定</li><li>画像設定</li><li>ブックマーク設定</li><li>アカウント</li><li>データ管理</li></ul><p>一般設定では、テーマ、Dynamic Color、言語、R-18 表示、アニメーション、ハプティクス、起動時の画面などを扱います。<br> 画像設定では、画質、先読み、列数、プロキシ、保存先を調整できます。<br> ブックマーク設定では、保存時の挙動を用途に応じて細かく変えられるようにしています。</p><p>設定項目が増えても迷いにくいよう、意味の近い項目を同じまとまりに置く構成を採っています。</p><h2 id="技術的なポイント" tabindex="-1">技術的なポイント <a class="header-anchor" href="#技術的なポイント" aria-label="Permalink to &quot;技術的なポイント&quot;">​</a></h2><p>Palleria は Jetpack Compose をベースに、Miuix のコンポーネント群を組み合わせて構成しています。<br> 実装では、見た目よりも状態管理と復帰性を優先しました。</p><p>意識しているポイントは次の通りです。</p><ul><li>画面ごとの責務を分離する</li><li>ViewModel に状態遷移を集約する</li><li>設定変更をアプリ全体へ一貫して反映する</li><li>保存や読み込みの進行状況を追跡できるようにする</li><li>認証切れや通信失敗から戻れる導線を残す</li></ul><p>画像表示まわりでは、高品質画像、先読み、プロキシ差し替えにも対応しています。<br> 通信量と表示速度のバランスを調整しながら、実用優先で使える構成にしています。</p><h2 id="これから" tabindex="-1">これから <a class="header-anchor" href="#これから" aria-label="Permalink to &quot;これから&quot;">​</a></h2><p>今後は、保存後の作品管理や検索の再訪性をさらに強めていく予定です。<br> また、一覧や遷移の反応速度、長く使う人向けの整理機能も引き続き詰めていきます。</p><p>Palleria は、毎日の Pixiv 利用の中で「あると助かる」を積み上げる方針で育てています。<br> 今後も、読む・探す・保存する、の流れを崩さずに改善を続けます。</p><hr><p>Palleria は Pixiv 公式とは無関係の非公式クライアントです。</p>',43)])])}const c=i(t,[["render",o]]);export{b as __pageData,c as default};
